rule('remove-outgoing-only','RemoveStarAllLine(tower) iterates WayLines but removes only IsFromThisTower=true. In a bidirectional line RemoveLine(tower) leaves the opposite direction. Inbound-only lines remain. This corrects any earlier interpretation that camp-change deletes every touching line.',[src('WayLineControl-RemoveStarAllLine-100665555.txt','00270b18','00270b38'),src('WayLine-RemoveLine-100665524.txt','00270675','002706a8')],transitionCases=[{'before':3,'remove':'small','after':2},{'before':3,'remove':'large','after':1},{'before':1,'remove':'small','after':0},{'before':1,'remove':'large','after':1},{'before':2,'remove':'small','after':2},{'before':2,'remove':'large','after':0}])
